    13→protocol NSEUserSessionProtocol {
    14→    var inviteAvatarsVisibility: InviteAvatars { get async }
    15→    var mediaPreviewVisibility: MediaPreviews { get async }
    16→    var threadsEnabled: Bool { get }
    17→    
    18→    func notificationItemProxy(roomID: String, eventID: String) async -> NotificationItemProxyProtocol?
