    58→
    59→    init(credentials: KeychainCredentials,
    60→         roomID: String,
    61→         clientSessionDelegate: ClientSessionDelegate,
    62→         appHooks: AppHooks,
    63→         appSettings: CommonSettingsProtocol) async throws {
    64→        sessionDirectories = credentials.restorationToken.sessionDirectories
    65→        userID = credentials.userID
    66→        self.appSettings = appSettings
    67→        
    68→        let homeserverURL = credentials.restorationToken.session.homeserverUrl
    69→        let clientBuilder = ClientBuilder
    70→            .baseBuilder(setupEncryption: false,
    71→                         httpProxy: URL(string: homeserverURL)?.globalProxy,
    72→                         slidingSync: .restored,
    73→                         sessionDelegate: clientSessionDelegate,
    74→                         appHooks: appHooks,
    75→                         enableOnlySignedDeviceIsolationMode: appSettings.enableOnlySignedDeviceIsolationMode,
    76→                         enableKeyShareOnInvite: appSettings.enableKeyShareOnInvite,
    77→                         requestTimeout: 15000,
    78→                         maxRequestRetryTime: 5000,
    79→                         threadsEnabled: appSettings.threadsEnabled)
    80→            .systemIsMemoryConstrained()
    81→            .sqliteStore(config: .init(dataPath: credentials.restorationToken.sessionDirectories.dataPath,
    82→                                       cachePath: credentials.restorationToken.sessionDirectories.cachePath)
    83→                    .passphrase(passphrase: credentials.restorationToken.passphrase))
    84→            .username(username: credentials.userID)
    85→            .homeserverUrl(url: homeserverURL)
    86→        
    87→        baseClient = try await clientBuilder.build()
    88→        delegateHandle = try baseClient.setDelegate(delegate: ClientDelegateWrapper())
    89→        
    90→        try await baseClient.restoreSessionWith(session: credentials.restorationToken.session,
    91→                                                roomLoadSettings: .one(roomId: roomID))
    92→        
