    96→    func notificationItemProxy(roomID: String, eventID: String) async -> NotificationItemProxyProtocol? {
    97→        do {
    98→            let notificationStatus = try await notificationClient.getNotification(roomId: roomID, eventId: eventID)
    99→                
   100→            switch notificationStatus {
   101→            case .event(let notification):
   102→                return NotificationItemProxy(notificationItem: notification,
   103→                                             eventID: eventID,
   104→                                             receiverID: userID,
   105→                                             roomID: roomID)
   106→            case .eventNotFound:
   107→                MXLog.error("Notification event not found - roomID: \(roomID) eventID: \(eventID)")
   108→                return nil
   109→            case .eventFilteredOut:
   110→                MXLog.warning("Notification event filtered out - roomID: \(roomID) eventID: \(eventID)")
   111→                return nil
   112→            }
   113→        } catch {
   114→            MXLog.error("Could not get notification's content creating an empty notification instead, error: \(error)")
   115→            return EmptyNotificationItemProxy(eventID: eventID, roomID: roomID, receiverID: userID)
   116→        }
   117→    }
   118→    
   119→    func roomForIdentifier(_ roomID: String) -> Room? {
   120→        do {
   121→            return try notificationClient.getRoom(roomId: roomID)
   122→        } catch {
   123→            MXLog.error("Failed retrieving room with error: \(error)")
   124→            return nil
   125→        }
   126→    }
   127→    
   128→    deinit {
   129→        delegateHandle?.cancel()
   130→    }
   131→}
