    23→class ElementCallService: NSObject, ElementCallServiceProtocol, PKPushRegistryDelegate, CXProviderDelegate {
    24→    private struct CallID: Equatable {
    25→        let callKitID: UUID
    26→        let roomID: String
    27→        let rtcNotificationID: String?
    28→    }
    29→    
    30→    private let pushRegistry: PKPushRegistry
    31→    private let callController = CXCallController()
    32→    private let callProvider: CXProviderProtocol
    33→    private let timeProvider: TimeProvider
    34→    
    35→    private weak var clientProxy: ClientProxyProtocol? {
    36→        didSet {
    37→            // There's a race condition where a call starts when the app has been killed and the
    38→            // observation set in `incomingCallID` occurs *before* the user session is restored.
    39→            // So observe when the client proxy is set to fix this (the method guards for the call).
    40→            Task { await observeIncomingCall() }
    41→        }
    42→    }
    43→    
    44→    private var incomingCallRoomInfoCancellable: AnyCancellable?
    45→    private var incomingCallID: CallID? {
    46→        didSet {
    47→            Task { await observeIncomingCall() }
    48→        }
    49→    }
    50→    
    51→    private var endUnansweredCallTask: Task<Void, Never>?
    52→    
    53→    private var ongoingCallID: CallID? {
    54→        didSet { ongoingCallRoomIDSubject.send(ongoingCallID?.roomID) }
    55→    }
    56→    
    57→    let ongoingCallRoomIDSubject = CurrentValueSubject<String?, Never>(nil)
    58→    var ongoingCallRoomIDPublisher: CurrentValuePublisher<String?, Never> {
    59→        ongoingCallRoomIDSubject.asCurrentValuePublisher()
    60→    }
    61→    
    62→    private let actionsSubject: PassthroughSubject<ElementCallServiceAction, Never> = .init()
    63→    var actions: AnyPublisher<ElementCallServiceAction, Never> {
    64→        actionsSubject.eraseToAnyPublisher()
    65→    }
    66→    
    67→    private var declineListenerHandle: TaskHandle?
    68→    
    69→    init(callProvider: CXProviderProtocol? = nil, timeProvider: TimeProvider? = nil) {
    70→        pushRegistry = PKPushRegistry(queue: nil)
    71→        
    72→        self.timeProvider = timeProvider ?? TimeProvider(clock: ContinuousClock(), now: Date.init)
    73→        
    74→        if let callProvider {
    75→            self.callProvider = callProvider
    76→        } else {
    77→            let configuration = CXProviderConfiguration()
    78→            configuration.supportsVideo = true
    79→            configuration.includesCallsInRecents = true
    80→            
    81→            if let callKitIcon = UIImage(named: "images/app-logo") {
    82→                configuration.iconTemplateImageData = callKitIcon.pngData()
    83→            }
    84→            
    85→            // https://stackoverflow.com/a/46077628/730924
    86→            configuration.supportedHandleTypes = [.generic]
    87→            
    88→            self.callProvider = CXProvider(configuration: configuration)
    89→        }
    90→        
    91→        super.init()
    92→        
    93→        pushRegistry.delegate = self
    94→        pushRegistry.desiredPushTypes = [.voIP]
    95→        
    96→        self.callProvider.setDelegate(self, queue: nil)
    97→    }
    98→    
    99→    func setClientProxy(_ clientProxy: any ClientProxyProtocol) {
   100→        self.clientProxy = clientProxy
