   103→    func setupCallSession(roomID: String, roomDisplayName: String) async {
   104→        // Drop any ongoing calls when starting a new one
   105→        if ongoingCallID != nil {
   106→            tearDownCallSession()
   107→        }
   108→        
   109→        // If this starting from a ring reuse those identifiers
   110→        // Make sure the roomID matches
   111→        let callID = if let incomingCallID, incomingCallID.roomID == roomID {
   112→            incomingCallID
   113→        } else {
   114→            CallID(callKitID: UUID(), roomID: roomID, rtcNotificationID: nil)
   115→        }
   116→        
   117→        incomingCallID = nil
   118→        ongoingCallID = callID
   119→        
   120→        // Don't bother starting another CallKit session as it won't work properly
   121→        // https://developer.apple.com/forums//thread/767949?answerId=812951022#812951022
   122→        
   123→        // let handle = CXHandle(type: .generic, value: roomDisplayName)
   124→        // let startCallAction = CXStartCallAction(call: callID.callKitID, handle: handle)
   125→        // startCallAction.isVideo = true
   126→        
   127→        // do {
   128→        //     try await callController.request(CXTransaction(action: startCallAction))
   129→        // } catch {
   130→        //     MXLog.error("Failed requesting start call action with error: \(error)")
   131→        // }
   132→    }
   133→    
   134→    func tearDownCallSession() {
   135→        tearDownCallSession(sendEndCallAction: true)
   136→    }
   137→    
   138→    func setAudioEnabled(_ enabled: Bool, roomID: String) {
   139→        guard let ongoingCallID else {
   140→            MXLog.error("Failed toggling call microphone, no calls running")
   141→            return
   142→        }
   143→        
   144→        guard ongoingCallID.roomID == roomID else {
   145→            MXLog.error("Failed toggling call microphone, rooms don't match: \(ongoingCallID.roomID) != \(roomID)")
   146→            return
   147→        }
   148→        
   149→        let transaction = CXTransaction(action: CXSetMutedCallAction(call: ongoingCallID.callKitID, muted: !enabled))
   150→        callController.request(transaction) { error in
   151→            if let error {
   152→                MXLog.error("Failed toggling call microphone with error: \(error)")
   153→            }
   154→        }
   155→    }
