   157→    // MARK: - PKPushRegistryDelegate
   158→    
   159→    func pushRegistry(_ registry: PKPushRegistry, didUpdate pushCredentials: PKPushCredentials, for type: PKPushType) { }
   160→    
   161→    func pushRegistry(_ registry: PKPushRegistry, didReceiveIncomingPushWith payload: PKPushPayload, for type: PKPushType, completion: @escaping () -> Void) {
   162→        guard let roomID = payload.dictionaryPayload[ElementCallServiceNotificationKey.roomID.rawValue] as? String else {
   163→            MXLog.error("Something went wrong, missing room identifier for incoming voip call: \(payload)")
   164→            return
   165→        }
   166→        
   167→        guard let rtcNotificationID = payload.dictionaryPayload[ElementCallServiceNotificationKey.rtcNotifyEventID.rawValue] as? String else {
   168→            MXLog.error("Something went wrong, missing rtc notification event identifier for incoming voip call: \(payload)")
   169→            return
   170→        }
   171→        
   172→        guard ongoingCallID?.roomID != roomID else {
   173→            MXLog.warning("Call already ongoing for room \(roomID), ignoring incoming push")
   174→            return
   175→        }
   176→        
   177→        let callID = CallID(callKitID: UUID(), roomID: roomID, rtcNotificationID: rtcNotificationID)
   178→        incomingCallID = callID
   179→        
   180→        guard let expirationDate = (payload.dictionaryPayload[ElementCallServiceNotificationKey.expirationDate.rawValue] as? Date) else {
   181→            MXLog.error("Something went wrong, missing expiration timestamp for incoming voip call: \(payload)")
   182→            return
   183→        }
   184→        
   185→        let nowDate = timeProvider.now()
   186→        
   187→        guard nowDate < expirationDate else {
   188→            MXLog.warning("Call expired for room \(roomID), ignoring incoming push")
   189→            return
   190→        }
   191→        
   192→        let ringDuration: Duration = .seconds(min(expirationDate.timeIntervalSince1970 - nowDate.timeIntervalSince1970, 90))
   193→        
   194→        let roomDisplayName = payload.dictionaryPayload[ElementCallServiceNotificationKey.roomDisplayName.rawValue] as? String
   195→        
   196→        let update = CXCallUpdate()
   197→        update.hasVideo = true
   198→        update.localizedCallerName = roomDisplayName
   199→        // https://stackoverflow.com/a/41230020/730924
   200→        update.remoteHandle = .init(type: .generic, value: roomID)
   201→        
   202→        callProvider.reportNewIncomingCall(with: callID.callKitID, update: update) { [weak self] error in
   203→            if let error {
   204→                MXLog.error("Failed reporting new incoming call with error: \(error)")
   205→            }
   206→            
   207→            self?.actionsSubject.send(.receivedIncomingCallRequest)
   208→            
   209→            completion()
   210→        }
   211→        
   212→        endUnansweredCallTask = Task { [weak self] in
   213→            try? await self?.timeProvider.clock.sleep(for: ringDuration)
   214→            
   215→            guard let self, !Task.isCancelled else {
   216→                return
   217→            }
   218→            
   219→            if let incomingCallID, incomingCallID.callKitID == callID.callKitID {
   220→                callProvider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: .unanswered)
   221→            }
   222→        }
   223→    }
   224→    
   225→    // MARK: - CXProviderDelegate
   226→    
   227→    func provider(_ provider: CXProvider, didActivate audioSession: AVAudioSession) {
   228→        MXLog.info("Call provider did activate audio session")
   229→    }
   230→    
   231→    func provider(_ provider: CXProvider, didDeactivate audioSession: AVAudioSession) {
   232→        MXLog.info("Call provider did deactivate audio session")
   233→    }
   234→    
   235→    func providerDidReset(_ provider: CXProvider) {
   236→        MXLog.info("Call provider did reset: \(provider)")
   237→    }
   238→    
   239→    func provider(_ provider: CXProvider, perform action: CXAnswerCallAction) {
   240→        guard let incomingCallID else {
   241→            MXLog.error("Failed answering incoming call, missing incomingCallID")
   242→            return
   243→        }
   244→        
   245→        // Fixes broken videos on EC web when a CallKit session is established.
   246→        //
   247→        // Reporting an ongoing call through `reportNewIncomingCall` + `CXAnswerCallAction`
   248→        // or `reportOutgoingCall:connectedAt:` will give exclusive access for media to the
   249→        // ongoing process, which is different than the WKWebKit is running on, making EC
   250→        // unable to aquire media streams.
   251→        // Reporting the call as ended imediately after answering it works around that
   252→        // as EC gets access to media again and EX builds the right UI in `setupCallSession`
   253→        //
   254→        // https://developer.apple.com/forums//thread/767949?answerId=812951022#812951022
   255→        //
   256→        // https://github.com/element-hq/element-x-ios/issues/3041
   257→        // https://forums.developer.apple.com/forums/thread/685268
   258→        // https://stackoverflow.com/questions/71483732/webrtc-running-from-wkwebview-avaudiosession-development-roadblock
   259→        
   260→        // First fullfill the action
   261→        action.fulfill()
   262→        
   263→        // And delay ending the call so that the app has enough time
   264→        // to get deeplinked into
   265→        DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
   266→            // Then end the and call rely on `setupCallSession` to create a new one
   267→            provider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: .remoteEnded)
   268→            
   269→            self.actionsSubject.send(.startCall(roomID: incomingCallID.roomID))
   270→            self.endUnansweredCallTask?.cancel()
   271→        }
   272→    }
   273→    
   274→    func provider(_ provider: CXProvider, perform action: CXSetMutedCallAction) {
   275→        if let ongoingCallID {
   276→            actionsSubject.send(.setAudioEnabled(!action.isMuted, roomID: ongoingCallID.roomID))
   277→        } else {
   278→            MXLog.error("Failed muting/unmuting call, missing ongoingCallID")
   279→        }
   280→        
   281→        action.fulfill()
   282→    }
   283→    
   284→    func provider(_ provider: CXProvider, perform action: CXEndCallAction) {
   285→        #if targetEnvironment(simulator)
   286→        // This gets called for no reason on simulators, where CallKit
   287→        // isn't even supported, ignore it.
   288→        #else
   289→        if let ongoingCallID {
   290→            actionsSubject.send(.endCall(roomID: ongoingCallID.roomID))
   291→        }
   292→        
   293→        if let incomingCallID {
   294→            Task {
   295→                await sendDeclineCallEvent(incomingCallID)
   296→            }
   297→        }
   298→        
   299→        tearDownCallSession(sendEndCallAction: false)
   300→        
   301→        action.fulfill()
   302→        #endif
   303→    }
   304→    
   305→    // MARK: - Private
   306→    
   307→    private func tearDownCallSession(sendEndCallAction: Bool = true) {
   308→        if sendEndCallAction, let ongoingCallID {
   309→            let transaction = CXTransaction(action: CXEndCallAction(call: ongoingCallID.callKitID))
   310→            callController.request(transaction) { error in
   311→                if let error {
   312→                    MXLog.error("Failed transaction with error: \(error)")
   313→                }
   314→            }
   315→        }
   316→        
   317→        ongoingCallID = nil
   318→    }
   319→    
   320→    private func sendDeclineCallEvent(_ incomingCallID: CallID) async {
   321→        guard let rtcNotificationID = incomingCallID.rtcNotificationID else {
   322→            MXLog.info("No rtc notification event to decline.")
   323→            return
   324→        }
   325→        
   326→        guard let clientProxy else {
   327→            MXLog.warning("A ClientProxy is needed to fetch the room.")
   328→            return
   329→        }
   330→        
   331→        guard case let .joined(roomProxy) = await clientProxy.roomForIdentifier(incomingCallID.roomID) else {
   332→            MXLog.warning("Failed to fetch a joined room for the incoming call.")
   333→            return
   334→        }
   335→        
   336→        _ = await roomProxy.declineCall(notificationID: rtcNotificationID)
   337→    }
   338→    
   339→    private func observeIncomingCall() async {
   340→        incomingCallRoomInfoCancellable = nil
   341→        
   342→        guard let incomingCallID else {
   343→            MXLog.info("No incoming call to observe for.")
   344→            return
   345→        }
   346→        
   347→        guard let clientProxy else {
   348→            MXLog.warning("A ClientProxy is needed to fetch the room.")
   349→            return
   350→        }
   351→        
   352→        guard case let .joined(roomProxy) = await clientProxy.roomForIdentifier(incomingCallID.roomID) else {
   353→            MXLog.warning("Failed to fetch a joined room for the incoming call.")
   354→            return
   355→        }
   356→        
   357→        roomProxy.subscribeToRoomInfoUpdates()
   358→        
   359→        incomingCallRoomInfoCancellable = roomProxy
   360→            .infoPublisher
   361→            .compactMap { ($0.hasRoomCall, $0.activeRoomCallParticipants) }
   362→            .removeDuplicates { $0 == $1 }
   363→            .drop { hasRoomCall, _ in
   364→                // Filter all updates before hasRoomCall becomes `true`. Then we can correctly
   365→                // detect its change to `false` to stop ringing when the caller hangs up.
   366→                !hasRoomCall
   367→            }
   368→            .sink { [weak self] hasOngoingCall, activeRoomCallParticipants in
   369→                guard let self else { return }
   370→                
   371→                let participants: [String] = activeRoomCallParticipants
   372→                
   373→                if !hasOngoingCall {
   374→                    MXLog.info("Call cancelled by remote")
   375→                    reportEndedCall(incomingCallID: incomingCallID, reason: .remoteEnded)
   376→                } else if participants.contains(roomProxy.ownUserID) {
   377→                    MXLog.info("Call answered elsewhere")
   378→                    reportEndedCall(incomingCallID: incomingCallID, reason: .answeredElsewhere)
   379→                }
   380→            }
   381→        
   382→        guard let rtcNotificationID = incomingCallID.rtcNotificationID else {
   383→            MXLog.warning("Decline: No RTC notification ID found for the incoming call.")
   384→            return
   385→        }
   386→        
   387→        MXLog.info("Observe decline events for notification \(rtcNotificationID)")
   388→        
   389→        let listener: CallDeclineListener = SDKListener { [weak self] senderID in
   390→            guard let self else { return }
   391→            
   392→            MXLog.debug("Call declined event received from \(senderID)")
   393→            
   394→            if senderID == roomProxy.ownUserID {
   395→                // Stop ringing!
   396→                MXLog.debug("Call declined elsewhere")
   397→                reportEndedCall(incomingCallID: incomingCallID, reason: .declinedElsewhere)
   398→            }
   399→        }
   400→        
   401→        guard case let .success(handle) = roomProxy.subscribeToCallDeclineEvents(rtcNotificationEventID: rtcNotificationID, listener: listener) else {
   402→            MXLog.error("Unable to listen for decline events.")
   403→            return
   404→        }
   405→        
   406→        declineListenerHandle = handle
   407→    }
   408→    
   409→    private func reportEndedCall(incomingCallID: CallID, reason: CXCallEndedReason) {
   410→        declineListenerHandle?.cancel()
   411→        declineListenerHandle = nil
   412→        endUnansweredCallTask?.cancel()
   413→        callProvider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: reason)
   414→    }
   415→}
