    14→final class NotificationManager: NSObject, NotificationManagerProtocol {
    15→    private let notificationCenter: UserNotificationCenterProtocol
    16→    private let appSettings: AppSettings
    17→    
    18→    private var userSession: UserSessionProtocol?
    19→    
    20→    private var cancellables = Set<AnyCancellable>()
